package org.apache.commons.compress.archivers.cpio;

import java.io.*;
import java.io.ByteArrayInputStream;
import java.io.EOFException;
import java.io.IOException;
import java.io.InputStream;
import java.math.*;
import java.util.*;
import org.apache.commons.compress.archivers.ArchiveEntry;
import org.apache.commons.compress.archivers.ArchiveInputStream;
import org.apache.commons.compress.archivers.cpio.CpioArchiveInputStream;
import org.apache.commons.compress.archivers.zip.ZipEncoding;
import org.apache.commons.compress.archivers.zip.ZipEncodingHelper;
import org.apache.commons.compress.utils.ArchiveUtils;
import org.apache.commons.compress.utils.CharsetNames;
import org.apache.commons.compress.utils.IOUtils;
import org.junit.*;
import org.junit.Assert;
import org.junit.Test;
import static org.junit.Assert.*;

public class CpioArchiveInputStream_skip_TriageGen0Test {

    /**
     * Helper to create a minimal valid CPIO stream simulation.
     * Since we are testing the skip logic which relies on read(), 
     * we can mock the behavior via a custom InputStream.
     */
    private static class MockInputStream extends InputStream {
        private final byte[] data;
        private int pos = 0;

        public MockInputStream(byte[] data) {
            this.data = data;
        }

        @Override
        public int read() {
            if (pos >= data.length) return -1;
            return data[pos++] & 0xFF;
        }

        @Override
        public int read(byte[] b, int off, int len) {
            if (pos >= data.length) return -1;
            int available = data.length - pos;
            int toRead = Math.min(len, available);
            System.arraycopy(data, pos, b, off, toRead);
            pos += toRead;
            return toRead;
        }
    }

    @Test(expected = IllegalArgumentException.class)
    public void testSkip_NegativeN() throws IOException {
        InputStream is = new ByteArrayInputStream(new byte[0]);
        CpioArchiveInputStream input = new CpioArchiveInputStream(is);
        input.skip(-1L);
    }

    @Test(expected = IOException.class)
    public void testSkip_ClosedStream() throws IOException {
        InputStream is = new ByteArrayInputStream(new byte[10]);
        CpioArchiveInputStream input = new CpioArchiveInputStream(is);
        input.close();
        input.skip(1);
    }

    @Test
    public void testSkip_ZeroN() throws IOException {
        byte[] data = new byte[10];
        InputStream is = new MockInputStream(data);
        CpioArchiveInputStream input = new CpioArchiveInputStream(is);

        long skipped = input.skip(0);
        Assert.assertEquals(0, skipped);
    }

    @Test
    public void testSkip_SmallN() throws IOException {
        byte[] data = new byte[10];
        InputStream is = new MockInputStream(data);
        CpioArchiveInputStream input = new CpioArchiveInputStream(is);

        // n < tmpbuf.length logic
        long skipped = input.skip(5);
        Assert.assertEquals(5, skipped);
    }

    @Test
    public void testSkip_LargeN_BelowIntMax() throws IOException {
        // To trigger the (len > this.tmpbuf.length) branch, 
        // we need n to be larger than the internal buffer.
        // Since we don't know the exact tmpbuf size, we use a large n.
        byte[] data = new byte[100];
        InputStream is = new MockInputStream(data);
        CpioArchiveInputStream input = new CpioArchiveInputStream(is);

        // We simulate a large n. Note: the loop uses Math.min(n, Integer.MAX_VALUE)
        // If n is larger than data, it hits the len == -1 condition.
        long skipped = input.skip(50);
        Assert.assertEquals(50, skipped);
    }

    @Test
    public void testSkip_NExceedsAvailable() throws IOException {
        byte[] data = new byte[10];
        InputStream is = new MockInputStream(data);
        CpioArchiveInputStream input = new CpioArchiveInputStream(is);

        // n is 20, but only 10 bytes available.
        // Should hit len == -1 and return total (10).
        long skipped = input.skip(20);
        Assert.assertEquals(10, skipped);
    }

    @Test
    public void testSkip_NIsExactlyIntMax() throws IOException {
        // This tests the max = (int) Math.min(n, Integer.MAX_VALUE) boundary
        byte[] data = new byte[100];
        InputStream is = new MockInputStream(data);
        CpioArchiveInputStream input = new CpioArchiveInputStream(is);

        // Use a value that is large but won't crash the test environment
        // In a real scenario, we'd check the boundary of Integer.MAX_VALUE
        long skipped = input.skip((long)Integer.MAX_VALUE);
        // Since data is only 100, it should return 100
        Assert.assertEquals(100, skipped);
    }

    @Test
    public void testSkip_VeryLargeN() throws IOException {
        byte[] data = new byte[5];
        InputStream is = new MockInputStream(data);
        CpioArchiveInputStream input = new CpioArchiveInputStream(is);

        // n > Integer.MAX_VALUE
        long skipped = input.skip(Long.MAX_VALUE);
        Assert.assertEquals(5, skipped);
    }
}
